import{_ as a,a as n,c as i,ac as l}from"./chunks/framework.BSuaGltH.js";const f=JSON.parse('{"title":"第三册：培养技能 · 本册介绍","description":"建议已熟悉基本时态、被动语态、常用从句与日常词汇，能独立阅读短篇叙事并写出连贯的六至八句段落。若完成时、主谓一致或不定式仍不稳定，可先复习第二册对应结构。","frontmatter":{"title":"第三册：培养技能 · 本册介绍","description":"建议已熟悉基本时态、被动语态、常用从句与日常词汇，能独立阅读短篇叙事并写出连贯的六至八句段落。若完成时、主谓一致或不定式仍不稳定，可先复习第二册对应结构。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","summary":"建议已熟悉基本时态、被动语态、常用从句与日常词汇，能独立阅读短篇叙事并写出连贯的六至八句段落。若完成时、主谓一致或不定式仍不稳定，可先复习第二册对应结构。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":false,"next":{"text":"第三册：培养技能 · 全册课程目录","link":"/life/english/new-concept/book-3/contents"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"第三册：培养技能 · 全册课程目录","link":"/life/english/new-concept/book-3/contents"}},"headers":[],"relativePath":"life/english/new-concept/book-3/overview.md","filePath":"life/english/new-concept/book-3/overview.md"}'),o={name:"life/english/new-concept/book-3/overview.md"};function t(r,e,c,s,h,p){return n(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="第三册-培养技能-·-本册介绍" tabindex="-1">第三册：培养技能 · 本册介绍 <a class="header-anchor" href="#第三册-培养技能-·-本册介绍" aria-label="Permalink to &quot;第三册：培养技能 · 本册介绍&quot;">​</a></h1><p><a href="/life/english/new-concept/book-3/overview">本册介绍</a> · <a href="/life/english/new-concept/book-3/contents">全册课程目录</a> · <a href="/life/english/new-concept/book-3/grammar">全册语法总结</a> · <a href="/life/english/new-concept/book-3/vocabulary">全册单词总结</a> · <a href="/life/english/new-concept/book-3/phrases">全册短语与句型</a> · <a href="/life/english/new-concept/book-3/mistakes">全册易错点</a> · <a href="/life/english/new-concept/book-3/review">综合复习与自测</a></p><p>本册按经典版第三册的六十课目录组织原创学习伴读，以叙事、人物、科学观察和社会议题训练长句理解与成段表达。课名与顺序用于定位正版教材，下面的主题说明、语法讲解、例句、练习和示范均为另行编写，不是课文、译文或教材原题。每课重点词只服务于本页学习任务，不声称覆盖教材完整词表。学习时先在自己的正版教材中阅读对应课文，再用这里的结构分析与输出任务检查迁移能力；没有教材也可以独立练习本页原创内容。对历史纪录、制度和科学推断尤其注意时间范围与证据边界，不将故事设定直接当作现实结论。</p><h2 id="版本与内容范围" tabindex="-1">版本与内容范围 <a class="header-anchor" href="#版本与内容范围" aria-label="Permalink to &quot;版本与内容范围&quot;">​</a></h2><p>Developing Skills；经典版 60 课。本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p><p>本栏目按连续课号组织学习单元；单元主题与复习任务为本站编排，便于分阶段学习，不作为各印次教材目录的替代。</p><h2 id="学习前提" tabindex="-1">学习前提 <a class="header-anchor" href="#学习前提" aria-label="Permalink to &quot;学习前提&quot;">​</a></h2><p>建议已熟悉基本时态、被动语态、常用从句与日常词汇，能独立阅读短篇叙事并写出连贯的六至八句段落。若完成时、主谓一致或不定式仍不稳定，可先复习第二册对应结构。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>识别长句的主干、修饰层次及逻辑连接，能把复杂结构还原成清楚的短句。</li><li>区分事实、转述、推测、反事实和个人评价，准确控制语气与时间视角。</li><li>围绕每课主题完成短篇叙事、说明或论述，并用明确条件和具体细节支持观点。</li><li>通过朗读、录音和复述检查连读中的语法线索，再迁移到自己的生活与工作表达。</li></ul><h2 id="学习方法与进度" tabindex="-1">学习方法与进度 <a class="header-anchor" href="#学习方法与进度" aria-label="Permalink to &quot;学习方法与进度&quot;">​</a></h2><p>每课分两次学习：第一次核对课名与主题，圈出本页例句主干，完成三题并先独立作答；第二次遮住示范完成口头输出，再写自己的版本。词汇按搭配记忆，不只背中文。朗读任务可使用本页原创句自行录音；本页未提供或假称存在教材音频。每二十课回顾一次，把最常错的时态、从句与介词各选两句改写，重点检查意义是否随形式改变。</p><h2 id="单元入口" tabindex="-1">单元入口 <a class="header-anchor" href="#单元入口" aria-label="Permalink to &quot;单元入口&quot;">​</a></h2><ul><li><a href="/life/english/new-concept/book-3/unit-01/overview">学习单元 1：第1—20课：观察、叙事与时间层次</a></li><li><a href="/life/english/new-concept/book-3/unit-02/overview">学习单元 2：第21—40课：人物、发现与句式控制</a></li><li><a href="/life/english/new-concept/book-3/unit-03/overview">学习单元 3：第41—60课：比较、论证与审慎表达</a></li></ul><h2 id="目录核对来源" tabindex="-1">目录核对来源 <a class="header-anchor" href="#目录核对来源" aria-label="Permalink to &quot;目录核对来源&quot;">​</a></h2><ul><li><a href="https://www.newconceptenglish.com/index.php?id=nce-3" target="_blank" rel="noopener noreferrer">NewConceptEnglish.com 第三册目录（核对英文课名、顺序与中文主题）</a></li><li><a href="https://www.youzack.com/ListeningExercise/AlbumIndex/?id=102" target="_blank" rel="noopener noreferrer">Youzack 第三册目录（交叉核对60课排列）</a></li></ul><p><a href="/life/english/new-concept/overview">返回系列介绍</a></p>',17)])])}const u=a(o,[["render",t]]);export{f as __pageData,u as default};
